@page "/catalog"
@rendermode InteractiveServer
@using sv_239179454f604491b66690eaf1b63b2c.Models
@using sv_239179454f604491b66690eaf1b63b2c.Services
@inject IProductService ProductService

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-container">
    @* Left Sidebar *@
    <aside class="catalog-sidebar">
        <h3>Filters</h3>

        <div class="filter-section">
            <h5>Categories</h5>
            @if (categories is not null)
            {
                @foreach (var category in categories)
                {
                    <div class="form-check">
                        <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                               checked="@selectedCategories.Contains(category)"
                               @onchange="(e) => ToggleCategory(category, (bool)e.Value!)" />
                        <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                    </div>
                }
            }
        </div>

        <div class="filter-section">
            <h5>Price Range</h5>
            <div class="mb-2">
                <label for="minPrice" class="form-label">Min Price</label>
                <input type="number" class="form-control" id="minPrice" @bind="minPrice" min="0" step="0.01" />
            </div>
            <div class="mb-2">
                <label for="maxPrice" class="form-label">Max Price</label>
                <input type="number" class="form-control" id="maxPrice" @bind="maxPrice" min="0" step="0.01" />
            </div>
        </div>

        <div class="filter-section">
            <div class="form-check">
                <input class="form-check-input" type="checkbox" id="inStockOnly" @bind="inStockOnly" />
                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
            </div>
        </div>

        <div class="filter-actions">
            <button class="btn btn-primary w-100 mb-2" @onclick="ApplyFilters">Apply Filters</button>
            <button class="btn btn-outline-secondary w-100" @onclick="ClearFilters">Clear Filters</button>
        </div>
    </aside>

    @* Main Content *@
    <main class="catalog-main">
        @if (errorMessage is not null)
        {
            <div class="alert alert-danger" role="alert">
                <strong>Error:</strong> @errorMessage
            </div>
        }
        else if (isLoading)
        {
            <div class="loading-indicator">
                <div class="spinner-border" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
                <p>Loading products...</p>
            </div>
        }
        else if (searchResult is null || searchResult.Items.Count == 0)
        {
            <div class="empty-state">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            @* Toolbar *@
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label for="sortBy" class="form-label me-2">Sort by:</label>
                    <select class="form-select" id="sortBy" @bind="sortBy" @bind:after="OnSortChanged">
